/* From Uiverse.io by ahmed150up - Tags: card */
.__UIV_SCOPE__ .card {
  width: 300px;
  background-color: #fff;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  border-radius: 10px;
  overflow: hidden;
}

.__UIV_SCOPE__ .header {
  background-color: #333;
  color: #fff;
  padding: 20px;
  text-align: center;
  font-size: 18px;
}

.__UIV_SCOPE__ .body {
  padding: 20px;
}

.__UIV_SCOPE__ .skill {
  display: flex;
  align-items: center;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .skill-name {
  width: 120px;
  font-size: 16px;
}

.__UIV_SCOPE__ .skill-level {
  width: 160px;
  height: 10px;
  background-color: #eee;
  border-radius: 10px;
  overflow: hidden;
  margin-left: 20px;
}

.__UIV_SCOPE__ .skill-percent {
  background-color: #333;
  height: 100%;
}

.__UIV_SCOPE__ .skill-percent-number {
  margin-left: 20px;
  font-size: 16px;
}
